/* The hymn index (/hymns, generated by tools/blog/build.mjs): a filter box over the list. Every hymn
 * carries its titles, first line, tune, writers, season and topics in data-search; typing hides the
 * hymns that do not match every word ("christmas" finds the Christmas hymns too). Hymns and tune pages
 * (data-kind "hymn" / "tune") share the list; the Hymns and Tunes buttons show one kind. The list itself is plain
 * HTML and works without this, and each season and occasion is a page of its own (/hymns/occasions/<slug>),
 * linked above the box. A ?q= in the address fills the box on arrival. Plain script, no build step. */
(function () {
  "use strict";
  var box = document.getElementById("hymn-find"), input = document.getElementById("hymn-filter");
  if (!box || !input) return;
  var items = Array.prototype.slice.call(document.querySelectorAll(".hymn-item[data-search]"));
  var sections = Array.prototype.slice.call(document.querySelectorAll(".hymn-letter"));
  var count = document.getElementById("hymn-count"), none = document.getElementById("hymn-none");
  var nav = document.querySelector(".az");
  box.hidden = false;

  function words(s) {
    var t = String(s || "").toLowerCase();
    if (t.normalize) t = t.normalize("NFKD").replace(/[̀-ͯ]/g, "");
    return t.replace(/[^a-z0-9]+/g, " ").trim().split(" ").filter(Boolean);
  }
  // "Hymns" or "Tunes" (a tune page has no words): the list shows only that kind while its button is pressed.
  var kind = null, kindButtons = Array.prototype.slice.call(box.querySelectorAll("button[data-kind]"));
  function apply() {
    var q = words(input.value), shown = 0;
    items.forEach(function (li) {
      var hay = " " + li.getAttribute("data-search") + " ";
      var ok = q.every(function (w) { return hay.indexOf(" " + w) >= 0; }) && (!kind || li.getAttribute("data-kind") === kind);
      li.hidden = !ok;
      if (ok) shown++;
    });
    sections.forEach(function (s) { s.hidden = !s.querySelector(".hymn-item:not([hidden])"); });
    if (nav) nav.hidden = q.length > 0 || !!kind;
    var noun = kind === "tune" ? [" tune", " tunes"] : [" hymn", " hymns"];
    count.textContent = q.length || kind ? shown + (shown === 1 ? noun[0] : noun[1]) + (q.length ? " found" : "") : "";
    none.hidden = shown > 0;
  }
  input.addEventListener("input", apply);
  kindButtons.forEach(function (b) {
    b.addEventListener("click", function () {
      kind = kind === b.getAttribute("data-kind") ? null : b.getAttribute("data-kind");
      kindButtons.forEach(function (o) { o.setAttribute("aria-pressed", String(o.getAttribute("data-kind") === kind)); });
      apply();
      if (window.nfTrack) try { window.nfTrack("Hymn filter: " + b.textContent); } catch (e) { /* ignore */ }
    });
  });
  try {
    var params = new URLSearchParams(window.location.search);
    var q = params.get("q"), k = params.get("kind");
    if (k) kindButtons.forEach(function (b) { if (b.getAttribute("data-kind") === k) { kind = k; b.setAttribute("aria-pressed", "true"); } });
    if (q) input.value = q;
    if (q || kind) apply();
  } catch (e) { /* an old browser: the box still works */ }
})();
